import type { DeliveryAddress, AddressErrors } from './types';

interface AddressFormProps {
  address: DeliveryAddress;
  errors: AddressErrors;
  disabled: boolean;
  onChange: (field: keyof DeliveryAddress, value: string) => void;
  onBlur: (field: keyof DeliveryAddress) => void;
}

interface FieldConfig {
  field: keyof DeliveryAddress;
  label: string;
  placeholder: string;
  required: boolean;
  autoComplete?: string;
  inputMode?: 'text' | 'tel' | 'numeric';
}

const FIELDS: FieldConfig[] = [
  { field: 'fullName', label: 'Full name', placeholder: 'Jane Doe', required: true, autoComplete: 'name' },
  { field: 'phone', label: 'Phone number', placeholder: '+1 555 123 4567', required: true, autoComplete: 'tel', inputMode: 'tel' },
  { field: 'city', label: 'City', placeholder: 'Springfield', required: true, autoComplete: 'address-level2' },
  { field: 'street', label: 'Street', placeholder: 'Evergreen Terrace', required: true, autoComplete: 'address-line1' },
  { field: 'building', label: 'Building / house no.', placeholder: '742', required: true, autoComplete: 'address-line2' },
  { field: 'apartment', label: 'Apartment (optional)', placeholder: '4B', required: false },
  { field: 'postalCode', label: 'Postal code (optional)', placeholder: '62704', required: false, autoComplete: 'postal-code' },
];

export function AddressForm({ address, errors, disabled, onChange, onBlur }: AddressFormProps) {
  return (
    <section className="checkout-section" aria-labelledby="delivery-address-heading">
      <h2 id="delivery-address-heading" className="checkout-section__title">
        Delivery address
      </h2>
      <div className="address-form">
        {FIELDS.map(({ field, label, placeholder, required, autoComplete, inputMode }) => {
          const inputId = `address-${field}`;
          const errorId = `${inputId}-error`;
          const hasError = Boolean(errors[field]);
          return (
            <div className="form-field" key={field}>
              <label htmlFor={inputId} className="form-field__label">
                {label}
                {required && (
                  <span className="form-field__required" aria-hidden="true">
                    {' '}
                    *
                  </span>
                )}
              </label>
              <input
                id={inputId}
                name={field}
                className={`form-field__input${hasError ? ' form-field__input--error' : ''}`}
                type="text"
                inputMode={inputMode}
                autoComplete={autoComplete}
                placeholder={placeholder}
                value={address[field]}
                disabled={disabled}
                aria-invalid={hasError}
                aria-describedby={hasError ? errorId : undefined}
                onChange={(e) => onChange(field, e.target.value)}
                onBlur={() => onBlur(field)}
              />
              {hasError && (
                <p id={errorId} className="form-field__error" role="alert">
                  {errors[field]}
                </p>
              )}
            </div>
          );
        })}

        <div className="form-field">
          <label htmlFor="address-comment" className="form-field__label">
            Comment for courier (optional)
          </label>
          <textarea
            id="address-comment"
            name="comment"
            className="form-field__input form-field__input--textarea"
            placeholder="E.g. gate code, preferred time"
            value={address.comment}
            disabled={disabled}
            rows={3}
            onChange={(e) => onChange('comment', e.target.value)}
            onBlur={() => onBlur('comment')}
          />
        </div>
      </div>
    </section>
  );
}
