// CheckoutScreen.tsx
import { useEffect, useMemo, useRef, useState } from 'react';
import { AddressForm } from './AddressForm';
import { CartItemsList } from './CartItemsList';
import { useTelegramWebApp } from './useTelegramWebApp';
import type { CartItem, DeliveryAddress, AddressErrors } from './types';
import './CheckoutScreen.css';

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  phone: '',
  city: '',
  street: '',
  building: '',
  apartment: '',
  postalCode: '',
  comment: '',
};

const DELIVERY_FEE = 4.99;
const PHONE_REGEX = /^\+?[0-9\s\-()]{7,20}$/;

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};
  if (!address.fullName.trim()) errors.fullName = "Enter the recipient's name.";
  if (!address.phone.trim()) {
    errors.phone = 'Enter a phone number.';
  } else if (!PHONE_REGEX.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number.';
  }
  if (!address.city.trim()) errors.city = 'Enter a city.';
  if (!address.street.trim()) errors.street = 'Enter a street.';
  if (!address.building.trim()) errors.building = 'Enter a building number.';
  return errors;
}

interface CheckoutScreenProps {
  cartItems: CartItem[];
  currency?: string;
  onBack: () => void;
  onPay: (address: DeliveryAddress, items: CartItem[], total: number) => Promise<void>;
}

export function CheckoutScreen({ cartItems, currency = 'USD', onBack, onPay }: CheckoutScreenProps) {
  const { tg } = useTelegramWebApp();
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const errors = useMemo(() => validateAddress(address), [address]);
  const isDirty = useMemo(() => Object.values(address).some((value) => value.trim() !== ''), [address]);
  const isValid = Object.keys(errors).length === 0 && cartItems.length > 0;

  const total = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0) + DELIVERY_FEE,
    [cartItems]
  );

  const visibleErrors = useMemo(
    () =>
      Object.fromEntries(
        Object.entries(errors).filter(([field]) => touched[field as keyof DeliveryAddress])
      ) as AddressErrors,
    [errors, touched]
  );

  function handleChange(field: keyof DeliveryAddress, value: string) {
    setAddress((prev) => ({ ...prev, [field]: value }));
    setSubmitError(null);
  }

  function handleBlur(field: keyof DeliveryAddress) {
    setTouched((prev) => ({ ...prev, [field]: true }));
  }

  function handleBack() {
    if (submitting) return;
    if (!isDirty) {
      onBack();
      return;
    }
    if (tg) {
      tg.showConfirm('Discard delivery details and go back to the cart?', (confirmed) => {
        if (confirmed) onBack();
      });
    } else if (window.confirm('Discard delivery details and go back to the cart?')) {
      onBack();
    }
  }

  // Kept fresh every render so the MainButton/fallback button always calls
  // the latest validation/state without re-registering Telegram's listener.
  const handlePayRef = useRef<() => void>(() => {});
  handlePayRef.current = () => {
    if (!isValid || submitting) return;
    setSubmitting(true);
    setSubmitError(null);
    tg?.MainButton.showProgress(true);
    tg?.HapticFeedback.impactOccurred('light');

    onPay(address, cartItems, total)
      .then(() => {
        tg?.HapticFeedback.notificationOccurred('success');
        tg?.disableClosingConfirmation();
        if (tg) {
          tg.showPopup({ title: 'Order placed', message: 'Your payment was successful.', buttons: [{ type: 'ok' }] });
        }
      })
      .catch((error: unknown) => {
        const message = error instanceof Error ? error.message : 'Payment failed. Please try again.';
        setSubmitError(message);
        tg?.HapticFeedback.notificationOccurred('error');
        tg?.showAlert(message);
      })
      .finally(() => {
        setSubmitting(false);
        tg?.MainButton.hideProgress();
        tg?.hideKeyboard?.();
      });
  };

  // Host owns back-navigation: show/hide Telegram's BackButton, never draw our own arrow.
  useEffect(() => {
    if (!tg) return;
    tg.BackButton.show();
    const listener = () => handleBack();
    tg.BackButton.onClick(listener);
    return () => {
      tg.BackButton.offClick(listener);
      tg.BackButton.hide();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tg, isDirty, submitting]);

  // Host owns the primary action: Telegram's MainButton is the "Pay" button.
  useEffect(() => {
    if (!tg) return;
    tg.MainButton.setText(
      `Pay ${new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(total)}`
    );
    tg.MainButton.show();
    const listener = () => handlePayRef.current();
    tg.MainButton.onClick(listener);
    return () => {
      tg.MainButton.offClick(listener);
    };
  }, [tg, currency, total]);

  useEffect(() => {
    if (!tg) return;
    if (isValid && !submitting) {
      tg.MainButton.enable();
    } else {
      tg.MainButton.disable();
    }
  }, [tg, isValid, submitting]);

  // Warn before the host lets a swipe-down discard unsaved address input.
  useEffect(() => {
    if (!tg) return;
    if (isDirty) {
      tg.enableClosingConfirmation();
    } else {
      tg.disableClosingConfirmation();
    }
  }, [tg, isDirty]);

  // This screen scrolls (item list + form), so give swipes back to the page.
  useEffect(() => {
    if (!tg || !tg.isVersionAtLeast('7.7')) return;
    tg.disableVerticalSwipes();
    return () => tg.enableVerticalSwipes();
  }, [tg]);

  // Match header/bottom-bar colour to the page so there's no seam with host chrome.
  useEffect(() => {
    if (!tg) return;
    if (tg.isVersionAtLeast('6.1')) {
      tg.setHeaderColor('secondary_bg_color');
      tg.setBackgroundColor('secondary_bg_color');
    }
    if (tg.isVersionAtLeast('7.10')) {
      tg.setBottomBarColor('secondary_bg_color');
    }
  }, [tg]);

  const isStandalone = !tg;

  return (
    <div className={`checkout-screen${isStandalone ? ' checkout-screen--standalone' : ''}`}>
      {isStandalone && (
        <header className="checkout-fallback-header">
          <button
            type="button"
            className="checkout-fallback-back"
            onClick={handleBack}
            aria-label="Back to cart"
          >
            ← Back to cart
          </button>
        </header>
      )}

      <main className="checkout-content">
        <CartItemsList items={cartItems} currency={currency} deliveryFee={DELIVERY_FEE} />
        <AddressForm
          address={address}
          errors={visibleErrors}
          disabled={submitting}
          onChange={handleChange}
          onBlur={handleBlur}
        />
        {submitError && (
          <p className="checkout-error" role="alert">
            {submitError}
          </p>
        )}
      </main>

      {isStandalone && (
        <footer className="checkout-fallback-footer">
          <button
            type="button"
            className="checkout-fallback-pay"
            disabled={!isValid || submitting}
            onClick={() => handlePayRef.current()}
          >
            {submitting
              ? 'Processing…'
              : `Pay ${new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(total)}`}
          </button>
        </footer>
      )}
    </div>
  );
}
