  background: var(--accent-solid);
  color: var(--accent-solid-foreground);
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
}

.checkout-fallback-pay:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
```

Usage:

```tsx
<CheckoutScreen
  cartItems={cartItems}
  currency="USD"
  onBack={() => navigate('/cart')}
  onPay={async (address, items, total) => {
    await api.placeOrder({ address, items, total });
  }}
/>
```

Notes on the platform-driven decisions: the Pay button is Telegram's **MainButton** (bottom bar), disabled until the address form validates and showing a progress spinner during `onPay`; "back to cart" is Telegram's **BackButton**, which confirms via `showConfirm` if the form is dirty before leaving; colours come entirely from `--tg-theme-*` CSS variables so light/dark and custom client themes work without extra code; layout respects `viewportStableHeight` and safe-area insets; closing confirmation is toggled on/off with form dirtiness so a swipe-down can't silently discard input. The on-page header/footer buttons only render when `window.Telegram.WebApp` is absent, so the screen is testable in a normal browser during development.
